// Paso 279 · v0.57.0 · Tablero «Calidad de la contabilidad» y aviso de saldos al revés: migración 0084 y prueba fase 78
//   (lista de control, rankings de cuentas al revés y de clientes con vencido, y las cuentas al revés por partida)
//   y la fase 77, que ya no supone que solo hay cinco tableros
// Uso (desde la carpeta RAÍZ del proyecto, no desde frontend):   node aplicar-paso279.mjs
// Se puede ejecutar dos veces sin problema. Respeta los finales de línea de Windows.
import fs from 'node:fs'
import path from 'node:path'

const FICHEROS = {"database/migrations/0084_quality_dashboard.sql": "-- =====================================================================\n-- 0084 · Tablero «Calidad de la contabilidad» y aviso de saldos al revés en el Balance (v0.57.0 · ADR 0057)\n-- ---------------------------------------------------------------------\n-- Diseño validado por Diosvely (diseno-v0.57.0.md, 01-11-2026): «meses sin cerrar» solo en las empresas mes a mes, las\n-- liquidaciones pendientes como error, el aviso del Balance completo (franja, partida y cuenta) y la 400 deudora en\n-- Existencias con aviso hasta compararla con el balance oficial de Sage y de ContaSol.\n--\n--   · LISTA DE CONTROL (erp.quality_checks): 7 filas a una fecha, cada una con su valor, su gravedad (ok, info, warning,\n--     error o «no aplica») y su pantalla. Salen de lo que ya existe: balance_anomalies, draft_problem, los periodos,\n--     las liquidaciones y la antigüedad de saldos. Los textos, en un catálogo (erp.quality_check_defs).\n--   · TARJETA «checklist» y dos fuentes nuevas de ranking: anomalies (cuentas con saldo al revés, con su nota) y\n--     overdue_customers (clientes con más importe vencido).\n--   · erp.fs_line_anomalies: cada cuenta con saldo al revés con la partida del Balance en la que se presenta (para el\n--     aviso del propio Balance). El ERP no compensa: avisa.\n--\n-- Se puede ejecutar dos veces.\n-- =====================================================================\n\n-- ---------- Los textos de la lista de control ----------\ncreate table if not exists erp.quality_check_defs (\n  code     text primary key,\n  sort     int  not null,\n  label    text not null,\n  label_en text not null,\n  help     text not null,\n  help_en  text not null,\n  unit     text not null check (unit in ('count', 'eur')),\n  link     text not null          -- pantalla de la empresa donde se arregla\n);\nalter table erp.quality_check_defs enable row level security;\ndrop policy if exists read on erp.quality_check_defs;\ncreate policy read on erp.quality_check_defs for select to authenticated using (true);\nrevoke all on erp.quality_check_defs from anon, public, authenticated;\ngrant select on erp.quality_check_defs to authenticated;\n\ninsert into erp.quality_check_defs (code, sort, label, label_en, help, help_en, unit, link) values\n ('anomalies', 10, 'Saldos al revés de su naturaleza', 'Balances against their nature',\n  'Cuentas con saldo contrario al normal (un proveedor deudor, una caja acreedora…). El ERP no las compensa: las presenta en la otra masa del balance y avisa. «Imposibles» = errores seguros.',\n  'Accounts with a balance against their normal side (a supplier with a debit balance, cash with a credit balance…). The ERP does not offset them: it presents them on the other side and warns. «Impossible» = certain errors.',\n  'count', 'checks'),\n ('drafts', 20, 'Asientos en edición', 'Draft entries',\n  'Borradores del ejercicio hasta la fecha. No cuentan en los informes hasta contabilizarlos; los que tienen un problema (descuadre, mes cerrado, cuenta controlada…) no se pueden contabilizar.',\n  'Drafts of the year up to the date. They do not count in reports until posted; those with a problem (unbalanced, closed month, controlled account…) cannot be posted.',\n  'count', 'entries'),\n ('open_months', 30, 'Meses sin cerrar', 'Months not closed',\n  'En la contabilidad mes a mes: meses ya terminados que siguen abiertos.',\n  'In month-by-month accounting: months already over that are still open.',\n  'count', 'entries'),\n ('settlements', 40, 'Liquidaciones pendientes', 'Pending tax returns',\n  'Trimestres terminados sin la liquidación de IVA / IGIC contabilizada. Tienen plazo y recargo.',\n  'Quarters already over without a posted VAT / IGIC return. They have a deadline and surcharges.',\n  'count', 'settlement'),\n ('overdue_in', 50, 'Cobros vencidos', 'Overdue receivables',\n  'Facturas emitidas pendientes de cobro y ya vencidas a la fecha. Error si alguna pasa de 90 días.',\n  'Sales invoices pending and already due at the date. Error if any is over 90 days.',\n  'eur', 'payments'),\n ('overdue_out', 60, 'Pagos vencidos', 'Overdue payables',\n  'Facturas recibidas pendientes de pago y ya vencidas a la fecha.',\n  'Purchase invoices pending and already due at the date.',\n  'eur', 'payments'),\n ('unreconciled', 70, 'Terceros sin conciliar', 'Unreconciled partners',\n  'Clientes y proveedores cuyo saldo contable no coincide con sus facturas pendientes: un cobro o pago sin vincular, o un apunte manual en su cuenta.',\n  'Customers and suppliers whose account balance does not match their pending invoices: an unlinked receipt or payment, or a manual entry on their account.',\n  'count', 'payments')\non conflict (code) do update set sort = excluded.sort, label = excluded.label, label_en = excluded.label_en, help = excluded.help,\n  help_en = excluded.help_en, unit = excluded.unit, link = excluded.link;\n\n-- ---------- La lista de control a una fecha ----------\n--   severity: ok · info (hay algo, pero es normal: borradores sin problema) · warning · error · na (no aplica)\ncreate or replace function erp.quality_checks(p_company uuid, p_year integer, p_to date default null, p_drafts boolean default false)\nreturns table(code text, value numeric, extra numeric, severity text)\nlanguage plpgsql stable set jit to 'off' as $$\n#variable_conflict use_column\ndeclare\n  v_prev_sim text := coalesce(nullif(current_setting('erp.simulate', true), ''), 'off');\n  fy erp.fiscal_years; co erp.companies; v_to date; n numeric; x numeric; has_inv boolean;\nbegin\n  if not erp.can_read(p_company) then raise exception 'Not allowed to read this company'; end if;\n  select * into fy from erp.fiscal_years f where f.company_id = p_company and f.year = p_year;\n  if fy.id is null then raise exception 'No fiscal year %', p_year; end if;\n  select * into co from erp.companies c where c.id = p_company;\n  v_to := least(coalesce(p_to, fy.ending_date), fy.ending_date);\n  if p_drafts then perform set_config('erp.simulate', 'on', true); end if;\n\n  -- 1) Saldos al revés (y cuántos son imposibles: severity error de balance_rules)\n  select count(*), count(*) filter (where a.severity = 'error') into n, x\n  from erp.balance_anomalies(p_company, p_year, null, v_to, p_drafts) a;\n  code := 'anomalies'; value := n; extra := x;\n  severity := case when x > 0 then 'error' when n > 0 then 'warning' else 'ok' end; return next;\n\n  -- 2) Asientos en edición (y cuántos tienen un problema: erp.draft_ready, la que puede usar la web)\n  select count(*), count(*) filter (where not erp.draft_ready(e.id)) into n, x\n  from erp.journal_entries e\n  where e.company_id = p_company and e.fiscal_year_id = fy.id and e.status = 'draft' and e.posting_date <= v_to;\n  code := 'drafts'; value := n; extra := x;\n  severity := case when x > 0 then 'warning' when n > 0 then 'info' else 'ok' end; return next;\n\n  -- 3) Meses sin cerrar: solo en la contabilidad mes a mes (en las demás todos están abiertos por diseño)\n  code := 'open_months'; extra := null;\n  if co.monthly then\n    select count(*) into n from erp.accounting_periods p\n    where p.fiscal_year_id = fy.id and p.status = 'open' and p.ending_date < least(v_to, current_date);\n    value := n; severity := case when n > 0 then 'warning' else 'ok' end;\n  else\n    value := null; severity := 'na';\n  end if;\n  return next;\n\n  -- 4) Liquidaciones pendientes: trimestres terminados (hasta la fecha) sin liquidación contabilizada del impuesto de la\n  --    empresa; solo si el impuesto está configurado\n  code := 'settlements'; extra := null;\n  if exists (select 1 from erp.tax_settlement_setup s where s.company_id = p_company and s.tax_type = erp.company_tax_type(p_company)) then\n    select count(*) into n from generate_series(1, 4) q\n    where erp.quarter_end(p_year, q) <= v_to and erp.quarter_end(p_year, q) < current_date\n      and not exists (select 1 from erp.tax_settlements s where s.company_id = p_company and s.tax_type = erp.company_tax_type(p_company)\n                      and s.year = p_year and s.quarter = q and s.status = 'posted');\n    value := n; severity := case when n > 0 then 'error' else 'ok' end;\n  else\n    value := null; severity := 'na';\n  end if;\n  return next;\n\n  -- 5) a 7) Vencidos y terceros sin conciliar: de la antigüedad de saldos; solo si la empresa tiene facturas en el ERP\n  --    (una empresa importada solo trae asientos)\n  has_inv := exists (select 1 from erp.invoices i where i.company_id = p_company);\n  code := 'overdue_in';\n  if has_inv then\n    select coalesce(sum(a.d1_30 + a.d31_60 + a.d61_90 + a.d90_plus), 0), coalesce(sum(a.d90_plus), 0) into n, x\n    from erp.aging(p_company, 'sale', v_to) a;\n    value := n; extra := x; severity := case when x > 0 then 'error' when n > 0 then 'warning' else 'ok' end;\n  else value := null; extra := null; severity := 'na'; end if;\n  return next;\n\n  code := 'overdue_out';\n  if has_inv then\n    select coalesce(sum(a.d1_30 + a.d31_60 + a.d61_90 + a.d90_plus), 0), coalesce(sum(a.d90_plus), 0) into n, x\n    from erp.aging(p_company, 'purchase', v_to) a;\n    value := n; extra := x; severity := case when n > 0 then 'warning' else 'ok' end;\n  else value := null; extra := null; severity := 'na'; end if;\n  return next;\n\n  code := 'unreconciled'; extra := null;\n  if has_inv then\n    select count(*) into n from (\n      select a.total, a.account_balance from erp.aging(p_company, 'sale', v_to) a\n      union all\n      select a.total, a.account_balance from erp.aging(p_company, 'purchase', v_to) a) z\n    where z.total <> z.account_balance;\n    value := n; severity := case when n > 0 then 'warning' else 'ok' end;\n  else value := null; severity := 'na'; end if;\n  return next;\n\n  perform set_config('erp.simulate', v_prev_sim, true);\nend $$;\nrevoke execute on function erp.quality_checks(uuid, integer, date, boolean) from anon, public;\ngrant execute on function erp.quality_checks(uuid, integer, date, boolean) to authenticated;\n\n-- La tarjeta: cada fila con sus textos y su pantalla\ncreate or replace function erp.quality_card(p_company uuid, p_year integer, p_to date, p_drafts boolean)\nreturns jsonb language sql stable as $$\n  select coalesce(jsonb_agg(jsonb_build_object(\n           'code', q.code, 'label', d.label, 'label_en', d.label_en, 'help', d.help, 'help_en', d.help_en,\n           'unit', d.unit, 'link', d.link, 'value', q.value, 'extra', q.extra, 'severity', q.severity) order by d.sort), '[]')\n  from erp.quality_checks(p_company, p_year, p_to, p_drafts) q\n  join erp.quality_check_defs d on d.code = q.code;\n$$;\nrevoke execute on function erp.quality_card(uuid, integer, date, boolean) from anon, public;\ngrant execute on function erp.quality_card(uuid, integer, date, boolean) to authenticated;\n\n-- ---------- El aviso del Balance: cada cuenta con saldo al revés y su partida ----------\ncreate or replace function erp.fs_line_anomalies(p_company uuid, p_year integer, p_to date default null, p_drafts boolean default false)\nreturns table(line_code text, account_no text, name text, name_en text, balance numeric, expected text, severity text, note text, note_en text)\nlanguage plpgsql stable set jit to 'off' as $$\n#variable_conflict use_column\ndeclare v_prev_sim text := coalesce(nullif(current_setting('erp.simulate', true), ''), 'off');\nbegin\n  if not erp.can_read(p_company) then raise exception 'Not allowed to read this company'; end if;\n  if p_drafts then perform set_config('erp.simulate', 'on', true); end if;\n  return query\n  select c.line_code, a.account_no, a.name, a.name_en, a.balance, a.expected, a.severity, a.note, a.note_en\n  from erp.balance_anomalies(p_company, p_year, null, p_to, p_drafts) a\n  join erp.fs_classified_accounts(p_company, p_year, 'balance', p_to) c on c.account_no = a.account_no\n  order by c.line_code, a.account_no;\n  perform set_config('erp.simulate', v_prev_sim, true);\nend $$;\nrevoke execute on function erp.fs_line_anomalies(uuid, integer, date, boolean) from anon, public;\ngrant execute on function erp.fs_line_anomalies(uuid, integer, date, boolean) to authenticated;\n\n-- ---------- Catálogo: la lista de control y las dos fuentes de ranking nuevas ----------\nalter table erp.dash_widgets drop constraint if exists dash_widgets_kind_check;\nalter table erp.dash_widgets add constraint dash_widgets_kind_check check (kind in ('kpis', 'bars', 'lines', 'table', 'ranking', 'checklist'));\nalter table erp.dash_widgets drop constraint if exists dash_widgets_source_check;\nalter table erp.dash_widgets add constraint dash_widgets_source_check\n  check ((kind = 'ranking') = (source is not null)\n         and (source is null or source in ('customers', 'suppliers', 'expense_groups', 'anomalies', 'overdue_customers'))\n         and top_n between 1 and 50);\n\n-- ---------- El ranking, con la nota de cada fila (0084: cuentas con saldo al revés y clientes con vencido) ----------\n-- Cambian las columnas que devuelve (se añade la nota): hay que borrarla y crearla de nuevo\ndrop function if exists erp.dash_ranking(uuid, integer, date, text);\ncreate or replace function erp.dash_ranking(p_company uuid, p_year integer, p_to date, p_source text)\nreturns table(key text, label text, amount numeric, note text, note_en text)\nlanguage sql stable security definer set search_path = erp, public as $$\n  with ent as (\n    select e.id\n    from erp.journal_entries e\n    where e.fiscal_year_id = (select fy.id from erp.fiscal_years fy where fy.company_id = p_company and fy.year = p_year)\n      and e.company_id = p_company and erp.counts_in_reports(e.status, e.id) and e.entry_type = 'normal'\n      and (p_to is null or e.posting_date <= p_to)\n      and p_source in ('customers', 'suppliers') and erp.can_report(p_company)\n    offset 0\n  ), lin as (\n    select l.entry_id, g.account_no, g.name, l.debit - l.credit as net\n    from ent e\n    join erp.journal_lines l on l.entry_id = e.id and l.company_id = p_company\n    join erp.gl_accounts g on g.id = l.gl_account_id\n  ), party as (\n    -- lo que mueve cada tercero en el asiento (para repartir si hay varios)\n    select entry_id, account_no, name, abs(sum(net)) as w\n    from lin\n    where case p_source when 'customers' then left(account_no, 2) in ('43', '44') else left(account_no, 2) in ('40', '41') end\n    group by entry_id, account_no, name\n    having sum(net) <> 0\n  ), amt as (\n    -- ventas: abonos − cargos de las cuentas de la cifra de negocios · compras: cargos − abonos de los grupos 6 y 2\n    select entry_id,\n           sum(case p_source when 'customers' then -net else net end) as a\n    from lin\n    where case p_source when 'customers' then left(account_no, 3) in ('700', '701', '702', '703', '704', '705', '706', '708', '709')\n                        else left(account_no, 1) in ('6', '2') end\n    group by entry_id\n    having sum(net) <> 0\n  ), alloc as (\n    select p.account_no as key, p.name as label, a.a * p.w / sum(p.w) over (partition by p.entry_id) as v\n    from amt a join party p on p.entry_id = a.entry_id\n    union all\n    select null, null, a.a from amt a where not exists (select 1 from party p where p.entry_id = a.entry_id)\n  )\n  select key, max(label), round(sum(v), 2), null::text, null::text from alloc group by key having round(sum(v), 2) <> 0\n  union all\n  -- gastos por naturaleza: los subgrupos del grupo 6 de la PyG, con el nombre del PGC\n  select s.key, coalesce(sg.name, s.key), s.amount, null::text, null::text\n  from (select left(c.account_no, 2) as key, sum(c.balance) as amount\n        from erp.fs_classified_at(p_company, p_year, 'pyg', array[p_to]) c\n        where p_source = 'expense_groups' and c.account_no like '6%'\n        group by left(c.account_no, 2) having sum(c.balance) <> 0) s\n  left join erp.pgc_subgroups sg on sg.subgroup = s.key\n  union all\n  -- 0084 · cuentas con saldo al revés: el importe en valor absoluto y la nota de balance_rules (qué suele ser)\n  select a.account_no, a.name, abs(a.balance), a.note, a.note_en\n  from erp.balance_anomalies(p_company, p_year, null, p_to, erp.simulating()) a\n  where p_source = 'anomalies' and erp.can_report(p_company)\n  union all\n  -- 0084 · clientes con importe vencido a la fecha (de la antigüedad de saldos)\n  select a.partner_account_no, a.partner_name, a.d1_30 + a.d31_60 + a.d61_90 + a.d90_plus,\n         -- (sin el importe en el texto: el formato de los números depende del servidor; el importe va en la fila)\n         case when a.d90_plus > 0 then 'Tiene facturas vencidas hace más de 90 días.' end,\n         case when a.d90_plus > 0 then 'Has invoices more than 90 days overdue.' end\n  from erp.aging(p_company, 'sale', p_to) a\n  where p_source = 'overdue_customers' and erp.can_report(p_company) and a.d1_30 + a.d31_60 + a.d61_90 + a.d90_plus > 0;\n$$;\n\ncreate or replace function erp.dash_ranking_card(p_company uuid, p_year integer, p_to date, p_prev_to date, p_has_prev boolean,\n                                                 p_source text, p_top int, p_sales numeric, p_sales_prev numeric)\nreturns jsonb language sql stable as $$\n  with cur as (select * from erp.dash_ranking(p_company, p_year, p_to, p_source)),\n       prv as (select * from erp.dash_ranking(p_company, p_year - 1, p_prev_to, p_source) where p_has_prev),\n       ranked as (select c.*, row_number() over (order by c.amount desc, c.key) as n from cur c where c.key is not null),\n       top as (select r.*, (select p.amount from prv p where p.key = r.key) as prev from ranked r where r.n <= p_top)\n  select jsonb_build_object(\n    'source', p_source,\n    'base', case p_source when 'expense_groups' then 'sales' when 'anomalies' then 'none' else 'total' end,\n    'rows', coalesce((select jsonb_agg(jsonb_build_object('key', key, 'label', label, 'value', amount, 'prev', prev, 'note', note, 'note_en', note_en) order by n) from top), '[]'),\n    'rest', jsonb_build_object(\n      'count', (select count(*) from ranked where n > p_top),\n      'value', (select coalesce(sum(amount), 0) from ranked where n > p_top),\n      'prev', case when p_has_prev then (select coalesce(sum(p.amount), 0) from prv p\n                                         where p.key is not null and p.key not in (select key from top)) end),\n    'none', jsonb_build_object(\n      'value', (select coalesce(sum(amount), 0) from cur where key is null),\n      'prev', case when p_has_prev then (select coalesce(sum(amount), 0) from prv where key is null) end),\n    'total', jsonb_build_object(\n      'value', (select coalesce(sum(amount), 0) from cur),\n      'prev', case when p_has_prev then (select coalesce(sum(amount), 0) from prv) end),\n    'sales', jsonb_build_object('value', p_sales, 'prev', p_sales_prev));\n$$;\n\nrevoke execute on function erp.dash_ranking(uuid, integer, date, text) from anon, public;\ngrant execute on function erp.dash_ranking(uuid, integer, date, text) to authenticated;\n\n-- ---------- El tablero con la lista de control (lo demás, igual que en la 0083) ----------\ncreate or replace function erp.dashboard_data(p_company uuid, p_dashboard text, p_year integer,\n                                              p_to_date date default null, p_drafts boolean default false)\nreturns jsonb language plpgsql stable set jit to 'off' as $$\ndeclare\n  v_prev_sim text := coalesce(nullif(current_setting('erp.simulate', true), ''), 'off');\n  d erp.dashboards; fy erp.fiscal_years; fy0 erp.fiscal_years;\n  v_to date; v_prev_to date; ends date[]; ends0 date[] := '{}';\n  cur jsonb; prev jsonb; s_cur jsonb := '[]'; s_prev jsonb := '[]'; widgets jsonb; e date; i int;\n  need_series boolean; vals jsonb;\nbegin\n  if not erp.can_read(p_company) then raise exception 'Not allowed to read this company'; end if;\n  select * into d from erp.dashboards where code = p_dashboard;\n  if d.code is null then raise exception 'Unknown dashboard: %', p_dashboard; end if;\n  select * into fy from erp.fiscal_years where company_id = p_company and year = p_year;\n  if fy.id is null then raise exception 'No fiscal year %', p_year; end if;\n  select * into fy0 from erp.fiscal_years where company_id = p_company and year = p_year - 1;\n  if p_drafts then perform set_config('erp.simulate', 'on', true); end if;\n\n  v_to := least(coalesce(p_to_date, fy.ending_date), fy.ending_date);\n  v_prev_to := (v_to - interval '1 year')::date;            -- la misma fecha del año anterior (29/02 → 28/02)\n  -- Las series, solo si el tablero tiene gráficos: cada fin de mes hasta la fecha (este año) y el año anterior entero.\n  -- Todas las fechas de un ejercicio se calculan juntas (una pasada por el diario).\n  need_series := exists (select 1 from erp.dash_widgets w where w.dashboard = p_dashboard and w.kind in ('bars', 'lines'));\n  ends := erp.dash_month_ends(fy.starting_date, fy.ending_date);\n  if fy0.id is not null then ends0 := erp.dash_month_ends(fy0.starting_date, fy0.ending_date); end if;\n  select jsonb_object_agg(x.at::text, x.v) into vals\n  from erp.dash_metric_values(p_company, p_year,\n         array[v_to] || case when need_series then array(select e2 from unnest(ends) e2 where e2 <= v_to) else '{}'::date[] end) x;\n  cur := vals -> v_to::text;\n  if need_series then\n    foreach e in array ends loop s_cur := s_cur || jsonb_build_array(vals -> e::text); end loop;   -- después de «hasta»: null\n  end if;\n  if fy0.id is not null then\n    select jsonb_object_agg(x.at::text, x.v) into vals\n    from erp.dash_metric_values(p_company, p_year - 1, array[v_prev_to] || case when need_series then ends0 else '{}'::date[] end) x;\n    prev := vals -> v_prev_to::text;\n    if need_series then\n      foreach e in array ends0 loop s_prev := s_prev || jsonb_build_array(vals -> e::text); end loop;\n    end if;\n  end if;\n\n  -- Cada tarjeta con sus métricas: valor, año anterior, zona de referencia y las series ya preparadas\n  --   mode month: lo de cada mes = acumulado del mes − acumulado del mes anterior\n  --   mode quarter (0082): lo de cada trimestre, con erp.dash_quarters\n  --   kind ranking (0083): las filas de erp.dash_ranking_card; sus métricas, vacías\n  --   kind checklist (0084): la lista de control de erp.quality_card\n  select coalesce(jsonb_agg(jsonb_build_object(\n           'sort', w.sort, 'kind', w.kind, 'size', w.size, 'mode', w.mode, 'label', w.label, 'label_en', w.label_en,\n           'help', w.help, 'help_en', w.help_en,\n           -- 0083: la tarjeta de ranking (los terceros o subgrupos, con el resto y el total)\n           'source', w.source, 'top_n', w.top_n,\n           'checklist', case when w.kind = 'checklist' then erp.quality_card(p_company, p_year, v_to, p_drafts) end,   -- 0084\n           'ranking', case when w.kind = 'ranking' then\n                        erp.dash_ranking_card(p_company, p_year, v_to, v_prev_to, fy0.id is not null, w.source, w.top_n,\n                                              (cur ->> 'SALES')::numeric, (prev ->> 'SALES')::numeric) end,\n           'items', (select coalesce(jsonb_agg(jsonb_build_object(\n               'code', m.code, 'label', m.label, 'label_en', m.label_en, 'unit', m.unit, 'link', m.link,\n               'help', m.help, 'help_en', m.help_en, 'ref_min', r.ref_min, 'ref_max', r.ref_max,\n               'value', cur -> m.code, 'prev', prev -> m.code,\n               'series', case when w.kind in ('bars', 'lines') and w.mode = 'quarter' then\n                                erp.dash_quarters(ends, s_cur, cur, v_to, m.code)\n                              when w.kind in ('bars', 'lines') then (\n                  select jsonb_agg(case when s.v is null or s.v = 'null'::jsonb then null\n                                        when w.mode = 'month' then to_jsonb((s.v ->> m.code)::numeric\n                                             - case when s.n = 1 then 0 else coalesce((s_cur -> (s.n::int - 2) ->> m.code)::numeric, 0) end)\n                                        else s.v -> m.code end order by s.n)\n                  from jsonb_array_elements(s_cur) with ordinality s(v, n)) end,\n               'series_prev', case when w.kind in ('bars', 'lines') and fy0.id is not null and w.mode = 'quarter' then\n                                erp.dash_quarters(ends0, s_prev, null, null, m.code)\n                              when w.kind in ('bars', 'lines') and fy0.id is not null then (\n                  select jsonb_agg(case when w.mode = 'month' then to_jsonb((s.v ->> m.code)::numeric\n                                             - case when s.n = 1 then 0 else coalesce((s_prev -> (s.n::int - 2) ->> m.code)::numeric, 0) end)\n                                        else s.v -> m.code end order by s.n)\n                  from jsonb_array_elements(s_prev) with ordinality s(v, n)) end)\n               order by k.n)\n             , '[]') from unnest(w.metrics) with ordinality k(code, n)\n             join erp.dash_metrics m on m.code = k.code\n             left join erp.ratio_defs r on r.code = m.ratio_code))\n         order by w.sort), '[]')\n    into widgets\n  from erp.dash_widgets w where w.dashboard = p_dashboard;\n\n  perform set_config('erp.simulate', v_prev_sim, true);\n  return jsonb_build_object(\n    'code', d.code, 'label', d.label, 'label_en', d.label_en, 'description', d.description, 'description_en', d.description_en,\n    'year', p_year, 'to', v_to, 'prev_to', case when fy0.id is not null then v_prev_to end, 'has_prev', fy0.id is not null,\n    'simulation', p_drafts, 'months', to_jsonb(ends), 'months_prev', to_jsonb(ends0), 'widgets', widgets,\n    'tax_type', erp.company_tax_type(p_company));   -- 0082: VAT o IGIC, para los títulos\nend $$;\n\n-- ---------- El tablero ----------\ninsert into erp.dashboards (code, sort, label, label_en, description, description_en) values\n ('calidad', 60, 'Calidad de la contabilidad', 'Accounting quality',\n  '¿Me puedo fiar de esta contabilidad a esta fecha y qué falta por hacer? La versión ligera de Comprobaciones: cada fila lleva a la pantalla donde se arregla.',\n  'Can I trust these books at this date and what is left to do? The light version of Checks: each row leads to the screen where it is fixed.')\non conflict (code) do update set sort = excluded.sort, label = excluded.label, label_en = excluded.label_en,\n  description = excluded.description, description_en = excluded.description_en;\n\ndelete from erp.dash_widgets where dashboard = 'calidad';\ninsert into erp.dash_widgets (dashboard, sort, kind, size, mode, source, top_n, label, label_en, help, help_en, metrics) values\n ('calidad', 10, 'checklist', 'full', 'end', null, 10, 'Lista de control', 'Checklist',\n  'A la fecha elegida. Para el análisis completo, Comprobaciones.', 'At the chosen date. For the full analysis, Checks.', '{}'),\n ('calidad', 20, 'ranking',   'half', 'end', 'anomalies', 10, 'Cuentas con saldo al revés', 'Accounts against their nature',\n  'Las de más importe, con lo que suele significar. El ERP no las compensa: revisa su libro mayor.',\n  'The largest ones, with what it usually means. The ERP does not offset them: check their ledger.', '{}'),\n ('calidad', 30, 'ranking',   'half', 'end', 'overdue_customers', 10, 'Clientes con más importe vencido', 'Customers with most overdue',\n  'Facturas emitidas pendientes y vencidas a la fecha (de la antigüedad de saldos).',\n  'Sales invoices pending and overdue at the date (from the ageing report).', '{}');\n\nnotify pgrst, 'reload schema';\n", "database/tests/test_fase78_quality_dashboard.sql": "-- =====================================================================\n-- PRUEBAS FASE 78 · Tablero «Calidad de la contabilidad» y aviso de saldos al revés en el Balance (migración 0084 ·\n-- v0.57.0)\n-- ---------------------------------------------------------------------\n-- Diseño validado por Diosvely (diseno-v0.57.0.md). Con el caso completo «Taller Atlántico SL» se comprueba lo que trae\n-- (Reservas voluntarias deudora, cliente dudoso vencido a más de 90 días) y, en una empresa con 2026 abierto, se provoca\n-- cada problema uno a uno:\n--   · un proveedor deudor (aviso; su ⚠ en Existencias; regresión de la 400: no se compensa con los acreedores) y sin\n--     conciliar con sus facturas; una caja acreedora (error); un borrador descuadrado;\n--   · un trimestre sin liquidar (error) y los meses sin cerrar en la contabilidad mes a mes;\n--   · la simulación, una empresa sin facturas («no aplica»), otra empresa no ve nada y rapidez con una empresa grande\n--     al lado.\n-- =====================================================================\n\\set ON_ERROR_STOP 1\n\\set QUIET 1\n\ninsert into auth.users (id, email) values ('00000000-0000-0000-0000-0000000000a1', 'owner@test.local'),\n                                          ('00000000-0000-0000-0000-0000000000b2', 'otro@test.local');\ninsert into erp.app_profiles (user_id, app_role, max_companies) values ('00000000-0000-0000-0000-0000000000a1', 'owner', null);\ninsert into erp.app_profiles (user_id, app_role, max_companies) values ('00000000-0000-0000-0000-0000000000b2', 'member', null)\non conflict (user_id) do nothing;\ncreate table public.ctx (k text primary key, e uuid);\ngrant all on public.ctx to authenticated;\ncreate or replace function public.falla(sql text, texto text) returns boolean language plpgsql as $$\nbegin\n  execute sql;\n  return false;\nexception when others then\n  if sqlerrm ilike '%' || texto || '%' then return true; end if;\n  raise notice 'error inesperado: %', sqlerrm;\n  return false;\nend $$;\ngrant execute on function public.falla(text, text) to authenticated;\n\n-- Una partida del Balance o de la PyG del ERP a una fecha\ncreate or replace function public.fs(c uuid, y int, st text, code text, d date) returns numeric language sql as $$\n  select coalesce((select x.amount from erp.financial_statement(c, y, st, d) x where x.code = $4), 0);\n$$;\ngrant execute on function public.fs(uuid, int, text, text, date) to authenticated;\n-- Una métrica de una tarjeta: la de un gráfico si la hay (lleva las series); si no, la de las cifras o la tabla\ncreate or replace function public.item(t jsonb, metric text) returns jsonb language sql as $$\n  select i from jsonb_array_elements(t -> 'widgets') w, jsonb_array_elements(w -> 'items') i\n  where i ->> 'code' = metric order by (w ->> 'kind') in ('kpis', 'table') limit 1;\n$$;\ngrant execute on function public.item(jsonb, text) to authenticated;\n\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\ndo $$\nbegin\n  insert into public.ctx values ('c', (erp.create_case_company('taller_atlantico', 'full')->>'company_id')::uuid);\nend $$;\nreset role;\n-- Una fila de la lista de control\ncreate or replace function public.q(c uuid, y int, code text, d date default null, sim boolean default false) returns jsonb language sql as $$\n  select to_jsonb(x) from erp.quality_checks(c, y, d, sim) x where x.code = $3;\n$$;\ngrant execute on function public.q(uuid, int, text, date, boolean) to authenticated;\n-- La tarjeta de ranking de una fuente\ncreate or replace function public.rk(t jsonb, src text) returns jsonb language sql as $$\n  select w -> 'ranking' from jsonb_array_elements(t -> 'widgets') w where w ->> 'source' = src;\n$$;\ngrant execute on function public.rk(jsonb, text) to authenticated;\n-- Un asiento contabilizado de dos líneas (debe, haber)\ncreate or replace function public.asiento(c uuid, d date, txt text, cta_d text, cta_h text, imp numeric, contabilizar boolean default true)\nreturns uuid language plpgsql as $$\ndeclare a uuid;\nbegin\n  insert into erp.journal_entries (company_id, fiscal_year_id, posting_date, description)\n  values (c, (select id from erp.fiscal_years where company_id = c and year = extract(year from d)), d, txt) returning id into a;\n  insert into erp.journal_lines (entry_id, gl_account_id, debit) values (a, (select id from erp.gl_accounts where company_id = c and account_no = cta_d), imp);\n  insert into erp.journal_lines (entry_id, gl_account_id, credit) values (a, (select id from erp.gl_accounts where company_id = c and account_no = cta_h), imp);\n  if contabilizar then perform erp.post_entry(a); end if;\n  return a;\nend $$;\ngrant execute on function public.asiento(uuid, date, text, text, text, numeric, boolean) to authenticated;\n\n-- ---------- El caso tal cual: lo que trae ----------\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\ndo $$\ndeclare c uuid := (select e from public.ctx where k = 'c'); t jsonb;\nbegin\n  assert (select count(*) from erp.quality_checks(c, 2026)) = 7, 'las 7 filas';\n  -- un saldo al revés real: Reservas voluntarias deudora (gastos de la ampliación de capital contra reservas)\n  assert public.q(c, 2026, 'anomalies') ->> 'value' = '1' and public.q(c, 2026, 'anomalies') ->> 'severity' = 'warning', 'Reservas voluntarias deudora';\n  assert public.q(c, 2026, 'drafts') ->> 'severity' = 'ok', 'sin borradores';\n  assert public.q(c, 2026, 'open_months') ->> 'severity' = 'na', 'no lleva la contabilidad mes a mes: no aplica';\n  assert public.q(c, 2026, 'settlements') ->> 'severity' = 'ok', 'los cuatro trimestres liquidados';\n  assert public.q(c, 2026, 'overdue_in') ->> 'severity' = 'error' and (public.q(c, 2026, 'overdue_in') ->> 'extra')::numeric = 2140,\n         'el cliente dudoso: 2.140 vencidos a más de 90 días';\n  assert public.q(c, 2026, 'unreconciled') ->> 'severity' = 'ok', 'los terceros cuadran con sus facturas';\n  t := erp.dashboard_data(c, 'calidad', 2026);\n  assert t ->> 'label' = 'Calidad de la contabilidad' and jsonb_array_length(t -> 'widgets') = 3;\n  assert jsonb_array_length((select w -> 'checklist' from jsonb_array_elements(t -> 'widgets') w where w ->> 'kind' = 'checklist')) = 7,\n         'la lista de control en el tablero';\n  assert public.rk(t, 'anomalies') -> 'rows' -> 0 ->> 'key' = '11300001' and public.rk(t, 'anomalies') ->> 'base' = 'none', 'la cuenta al revés, en el ranking';\n  assert public.rk(t, 'overdue_customers') -> 'rows' @> '[{\"key\": \"43000002\", \"note\": \"Tiene facturas vencidas hace más de 90 días.\"}]'::jsonb,\n         'el cliente dudoso, con su nota';\n  assert exists (select 1 from erp.fs_line_anomalies(c, 2026) a where a.account_no = '11300001' and a.line_code like 'PN%'),\n         'el aviso del Balance cae en el patrimonio neto';\n  raise notice 'OK  · el caso: Reservas voluntarias al revés, cliente dudoso vencido a más de 90 días y el resto en verde';\nend $$;\nreset role;\n\n-- ---------- Se provoca cada problema en una empresa con 2026 abierto ----------\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\ndo $$ begin\n  insert into public.ctx values ('abierta', (erp.create_case_company('taller_atlantico', 'until_closing')->>'company_id')::uuid);\nend $$;\nreset role;\nupdate erp.companies set control_mode = 'guided' where id = (select e from public.ctx where k = 'abierta');\ninsert into erp.gl_accounts (company_id, account_no, name, name_en, account_type, template_account, account_category)\nselect company_id, '57000001', 'Caja', 'Cash', account_type, '570', account_category\nfrom erp.gl_accounts where company_id = (select e from public.ctx where k = 'abierta') and account_no = '57200001';\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\ndo $$\ndeclare c uuid := (select e from public.ctx where k = 'abierta'); ai numeric; prov numeric; a uuid; n0 int;\nbegin\n  n0 := (public.q(c, 2026, 'anomalies') ->> 'value')::int;\n  ai := (select x.amount from erp.financial_statement(c, 2026, 'balance', null) x where x.code = 'AC.I');\n  prov := (select x.amount from erp.financial_statement(c, 2026, 'balance', null) x where x.code = 'PC.IV.1');\n  -- 1) un proveedor con saldo deudor (pago de más a Maquinaria Atlántica): aviso, y además sin conciliar\n  perform public.asiento(c, '2026-12-15', 'Pago duplicado', '40000002', '57200001', 5000);\n  assert (public.q(c, 2026, 'anomalies') ->> 'value')::int = n0 + 1 and public.q(c, 2026, 'anomalies') ->> 'severity' = 'warning', 'proveedor deudor: aviso';\n  assert exists (select 1 from erp.fs_line_anomalies(c, 2026) a where a.account_no = '40000002' and a.line_code like 'AC.I%'),\n         'su ⚠ cae en Existencias (como un anticipo, 407)';\n  -- regresión de la 400: no se compensa con los proveedores acreedores\n  assert (select x.amount from erp.financial_statement(c, 2026, 'balance', null) x where x.code = 'AC.I') = ai + 5000, 'Existencias + 5.000';\n  assert (select x.amount from erp.financial_statement(c, 2026, 'balance', null) x where x.code = 'PC.IV.1') = prov, 'Proveedores no cambia: no se compensa';\n  assert (public.q(c, 2026, 'unreconciled') ->> 'value')::int >= 1, 'el proveedor no cuadra con sus facturas';\n  -- 3) un borrador descuadrado\n  insert into erp.journal_entries (company_id, fiscal_year_id, posting_date, description)\n  values (c, (select id from erp.fiscal_years where company_id = c and year = 2026), '2026-12-20', 'Descuadrado') returning id into a;\n  insert into erp.journal_lines (entry_id, gl_account_id, debit) values (a, (select id from erp.gl_accounts where company_id = c and account_no = '57200001'), 10);\n  insert into erp.journal_lines (entry_id, gl_account_id, credit) values (a, (select id from erp.gl_accounts where company_id = c and account_no = '57000001'), 7);\n  assert public.q(c, 2026, 'drafts') @> '{\"value\": 1, \"extra\": 1, \"severity\": \"warning\"}'::jsonb, 'un borrador con problema';\n  delete from erp.journal_lines where entry_id = a;\n  delete from erp.journal_entries where id = a;\n  raise notice 'OK  · proveedor deudor (Existencias, sin compensar), borrador descuadrado';\nend $$;\n\n-- 2) una caja acreedora: el ERP no deja contabilizarla (está bloqueada para saldos al revés), pero puede llegar en un\n--    diario importado; se mete como una importación, sin disparadores\nreset role;\nset session_replication_role = replica;\nwith c as (select e as cid from public.ctx where k = 'abierta'),\n     ins as (insert into erp.journal_entries (company_id, fiscal_year_id, entry_no, posting_date, description, status)\n             select (select cid from c), (select id from erp.fiscal_years where company_id = (select cid from c) and year = 2026),\n                    90001, '2026-12-16', 'Importado: gasto pagado sin dinero en caja', 'posted' returning id)\ninsert into erp.journal_lines (company_id, entry_id, gl_account_id, debit, credit, line_no)\nselect (select cid from c), i.id, a.id, case when a.account_no = '62300001' then 100 else 0 end,\n       case when a.account_no = '57000001' then 100 else 0 end, case when a.account_no = '62300001' then 1 else 2 end\nfrom ins i cross join erp.gl_accounts a where a.company_id = (select cid from c) and a.account_no in ('62300001', '57000001');\nset session_replication_role = origin;\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\ndo $$\ndeclare c uuid := (select e from public.ctx where k = 'abierta');\nbegin\n  -- 2) una caja acreedora: imposible → error\n  assert public.q(c, 2026, 'anomalies') ->> 'severity' = 'error' and (public.q(c, 2026, 'anomalies') ->> 'extra')::int = 1, 'caja acreedora: error';\n  assert exists (select 1 from erp.fs_line_anomalies(c, 2026) a where a.account_no = '57000001' and a.severity = 'error' and a.line_code like 'PC%'),\n         'su ⚠ cae en el pasivo corriente';\n  raise notice 'OK  · caja acreedora importada: error, con su ⚠ en el pasivo corriente';\nend $$;\n\n-- 4) un trimestre sin liquidar (se anula la del 3T) y 5) la contabilidad mes a mes\nreset role;\ndo $$\ndeclare c uuid := (select e from public.ctx where k = 'abierta');\nbegin\n  -- solo se puede anular la última: primero la del 4T y después la del 3T\n  perform erp.cancel_tax_settlement((select id from erp.tax_settlements where company_id = c and year = 2026 and quarter = 4 and status = 'posted'));\n  perform erp.cancel_tax_settlement((select id from erp.tax_settlements where company_id = c and year = 2026 and quarter = 3 and status = 'posted'));\nend $$;\nupdate erp.companies set monthly = true where id = (select e from public.ctx where k = 'abierta');\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\ndo $$\ndeclare c uuid := (select e from public.ctx where k = 'abierta');\nbegin\n  -- el 3T ya terminó; el 4T cuenta solo si hoy ya pasó el 31/12/2026\n  assert (public.q(c, 2026, 'settlements') ->> 'value')::int = 1 + (current_date > '2026-12-31')::int\n     and public.q(c, 2026, 'settlements') ->> 'severity' = 'error', format('el 3T sin liquidar: %s', public.q(c, 2026, 'settlements'));\n  assert public.q(c, 2026, 'settlements', '2026-06-30') ->> 'value' = '0', 'a 30/06, el 3T todavía no había terminado';\n  assert (public.q(c, 2026, 'open_months') ->> 'value')::int > 0 and public.q(c, 2026, 'open_months') ->> 'severity' = 'warning',\n         'mes a mes: los meses terminados sin cerrar';\n  raise notice 'OK  · liquidación pendiente (error) y meses sin cerrar en la contabilidad mes a mes';\nend $$;\n\n-- ---------- Simulación: una caja acreedora en edición ----------\ndo $$\ndeclare c uuid := (select e from public.ctx where k = 'c'); a uuid; n int;\nbegin\n  -- (en el caso, 2026 está cerrado: se usa 2027)\n  n := (public.q(c, 2027, 'anomalies') ->> 'value')::int;\n  a := public.asiento(c, '2027-02-10', 'Caja acreedora (borrador)', '62300001', '57200001', 999999, false);\n  assert (public.q(c, 2027, 'anomalies') ->> 'value')::int = n, 'sin simulación, el borrador no cuenta';\n  assert (public.q(c, 2027, 'anomalies', null, true) ->> 'value')::int = n + 1, 'con simulación, el banco queda acreedor';\n  assert exists (select 1 from erp.fs_line_anomalies(c, 2027, null, true) x where x.account_no = '57200001'), 'y el Balance lo avisa';\n  assert not erp.simulating(), 'al terminar, la simulación se apaga';\n  delete from erp.journal_lines where entry_id = a;\n  delete from erp.journal_entries where id = a;\n  raise notice 'OK  · la simulación con un asiento en edición';\nend $$;\n\n-- ---------- Una empresa sin facturas (como una importada): vencidos y conciliación no aplican ----------\ndo $$\ndeclare c uuid; y int;\nbegin\n  insert into erp.companies (name, industry, tax_territory, created_by) values ('Importada', 'services', 'mainland', auth.uid()) returning id into c;\n  perform erp.create_fiscal_year(c, 2026);\n  y := 2026;\n  assert public.q(c, y, 'overdue_in') ->> 'severity' = 'na' and public.q(c, y, 'unreconciled') ->> 'severity' = 'na', 'sin facturas, no aplica';\n  assert public.q(c, y, 'settlements') ->> 'severity' in ('na', 'ok'), 'sin liquidaciones configuradas o al día';\n  raise notice 'OK  · sin facturas en el ERP: «no aplica»';\nend $$;\n\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000b2', false) \\gset\ndo $$\ndeclare c uuid := (select e from public.ctx where k = 'c');\nbegin\n  assert public.falla(format('select * from erp.quality_checks(%L, 2026)', c), 'Not allowed'), 'otra empresa no ve la lista';\n  assert public.falla(format('select * from erp.fs_line_anomalies(%L, 2026)', c), 'Not allowed'), 'ni el aviso del Balance';\n  assert not exists (select 1 from erp.dash_ranking(c, 2026, null, 'anomalies')), 'ni sus cuentas';\n  raise notice 'OK  · otra empresa no ve nada';\nend $$;\nreset role;\n\n-- ---------- El catálogo ----------\ndo $$\nbegin\n  assert (select count(*) from erp.quality_check_defs) = 7, 'los textos de las 7 filas';\n  assert (select count(*) from erp.dashboards) = 6, 'el Resumen de dirección y los cinco tableros nuevos';\n  assert public.falla($q$insert into erp.dash_widgets (dashboard, sort, kind, source, label, label_en, metrics) values ('calidad', 99, 'checklist', 'anomalies', 'x', 'x', '{}')$q$,\n                      'dash_widgets_source_check'), 'la lista de control no tiene fuente';\n  assert not has_function_privilege('anon', 'erp.quality_checks(uuid, integer, date, boolean)', 'execute');\n  assert not has_function_privilege('anon', 'erp.fs_line_anomalies(uuid, integer, date, boolean)', 'execute');\n  assert has_function_privilege('authenticated', 'erp.fs_line_anomalies(uuid, integer, date, boolean)', 'execute');\n  raise notice 'OK  · catálogo y permisos';\nend $$;\n\n-- ---------- Rápido, aunque al lado haya una empresa grande de otro usuario ----------\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000b2', false) \\gset\ndo $$ begin\n  insert into public.ctx values ('grande', (erp.create_case_company('taller_atlantico', 'until_closing')->>'company_id')::uuid);\nend $$;\nreset role;\nselect set_config('request.jwt.claim.sub', '', false) \\gset\nset session_replication_role = replica;\nwith c as (select e as cid from public.ctx where k = 'grande'),\n     fy as (select id from erp.fiscal_years where company_id = (select cid from c) and year = 2026),\n     ins as (insert into erp.journal_entries (company_id, fiscal_year_id, entry_no, posting_date, description, status)\n             select (select cid from c), (select id from fy), 100000 + g, date '2026-01-01' + (g % 360), 'volumen', 'posted'\n             from generate_series(1, 30000) g returning id)\ninsert into erp.journal_lines (company_id, entry_id, gl_account_id, debit, credit, line_no)\nselect (select cid from c), i.id, a.id, case when a.account_no = '62300001' then 10 else 0 end,\n       case when a.account_no = '57200001' then 10 else 0 end, case when a.account_no = '62300001' then 1 else 2 end\nfrom ins i cross join erp.gl_accounts a where a.company_id = (select cid from c) and a.account_no in ('62300001', '57200001');\nset session_replication_role = origin;\nanalyze erp.journal_entries;\nanalyze erp.journal_lines;\n\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\ndo $$\ndeclare c uuid := (select e from public.ctx where k = 'c'); t0 timestamptz; ms numeric;\nbegin\n  t0 := clock_timestamp();\n  perform erp.dashboard_data(c, 'calidad', 2027, '2027-06-30');\n  ms := extract(epoch from clock_timestamp() - t0) * 1000;\n  assert ms < 3000, format('el tablero tarda %s ms', round(ms));\n  raise notice 'OK  · el tablero en % ms con una empresa de 30.000 asientos al lado', round(ms);\nend $$;\nreset role;\n\n\\echo 'FASE 78 OK'\n", "database/tests/test_fase77_sales_expenses_dashboard.sql": "-- =====================================================================\n-- PRUEBAS FASE 77 · Tablero «Ventas y gastos» (migración 0083 · v0.56.0)\n-- ---------------------------------------------------------------------\n-- Diseño validado por Diosvely (diseno-v0.56.0.md). Con el caso completo «Taller Atlántico SL» se comprueba que:\n--   · el ranking de clientes suma la cifra de negocios y el de gastos por naturaleza, el grupo 6; el caso, al céntimo\n--     (Cliente General SL 118.000 €, Cliente Dudoso SL 2.000 €; Recambios Canarios SL 45.000 € y la inversión de\n--     Maquinaria Atlántica SL, 40.000 €, sin IGIC);\n--   · un asiento con dos clientes se reparte en proporción, un cobro no cuenta (regresión: si contara lo que se carga\n--     en la cuenta del cliente, el cliente «vendería» dos veces) y una rectificativa resta;\n--   · los N primeros y el «Resto», «hasta» con el año anterior, la simulación, otra empresa no ve nada y rapidez con\n--     una empresa grande al lado.\n-- =====================================================================\n\\set ON_ERROR_STOP 1\n\\set QUIET 1\n\ninsert into auth.users (id, email) values ('00000000-0000-0000-0000-0000000000a1', 'owner@test.local'),\n                                          ('00000000-0000-0000-0000-0000000000b2', 'otro@test.local');\ninsert into erp.app_profiles (user_id, app_role, max_companies) values ('00000000-0000-0000-0000-0000000000a1', 'owner', null);\ninsert into erp.app_profiles (user_id, app_role, max_companies) values ('00000000-0000-0000-0000-0000000000b2', 'member', null)\non conflict (user_id) do nothing;\ncreate table public.ctx (k text primary key, e uuid);\ngrant all on public.ctx to authenticated;\ncreate or replace function public.falla(sql text, texto text) returns boolean language plpgsql as $$\nbegin\n  execute sql;\n  return false;\nexception when others then\n  if sqlerrm ilike '%' || texto || '%' then return true; end if;\n  raise notice 'error inesperado: %', sqlerrm;\n  return false;\nend $$;\ngrant execute on function public.falla(text, text) to authenticated;\n\n-- Una partida del Balance o de la PyG del ERP a una fecha\ncreate or replace function public.fs(c uuid, y int, st text, code text, d date) returns numeric language sql as $$\n  select coalesce((select x.amount from erp.financial_statement(c, y, st, d) x where x.code = $4), 0);\n$$;\ngrant execute on function public.fs(uuid, int, text, text, date) to authenticated;\n-- Una métrica de una tarjeta: la de un gráfico si la hay (lleva las series); si no, la de las cifras o la tabla\ncreate or replace function public.item(t jsonb, metric text) returns jsonb language sql as $$\n  select i from jsonb_array_elements(t -> 'widgets') w, jsonb_array_elements(w -> 'items') i\n  where i ->> 'code' = metric order by (w ->> 'kind') in ('kpis', 'table') limit 1;\n$$;\ngrant execute on function public.item(jsonb, text) to authenticated;\n\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\ndo $$\nbegin\n  insert into public.ctx values ('c', (erp.create_case_company('taller_atlantico', 'full')->>'company_id')::uuid);\nend $$;\nreset role;\n-- La tarjeta de ranking de una fuente\ncreate or replace function public.rk(t jsonb, src text) returns jsonb language sql as $$\n  select w -> 'ranking' from jsonb_array_elements(t -> 'widgets') w where w ->> 'source' = src;\n$$;\ngrant execute on function public.rk(jsonb, text) to authenticated;\n-- El importe de una subcuenta en un ranking (null si no está entre los primeros)\ncreate or replace function public.rv(r jsonb, k text) returns numeric language sql as $$\n  select (x ->> 'value')::numeric from jsonb_array_elements(r -> 'rows') x where x ->> 'key' = k;\n$$;\ngrant execute on function public.rv(jsonb, text) to authenticated;\n-- Lo que suma un ranking: sus filas, el resto y lo que no tiene tercero\ncreate or replace function public.rsum(r jsonb) returns numeric language sql as $$\n  select coalesce((select sum((x ->> 'value')::numeric) from jsonb_array_elements(r -> 'rows') x), 0)\n         + (r -> 'rest' ->> 'value')::numeric + (r -> 'none' ->> 'value')::numeric;\n$$;\ngrant execute on function public.rsum(jsonb) to authenticated;\n\n-- ---------- Los rankings cuadran con la PyG ----------\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\ndo $$\ndeclare c uuid := (select e from public.ctx where k = 'c'); t jsonb; r jsonb;\nbegin\n  t := erp.dashboard_data(c, 'ventas', 2026);\n  assert t ->> 'label' = 'Ventas y gastos';\n  assert (select count(*) from jsonb_array_elements(t -> 'widgets')) = 6, 'las 6 tarjetas';\n  -- Clientes: su total (con el resto y «sin cliente») = la cifra de negocios\n  r := public.rk(t, 'customers');\n  assert public.rsum(r) = public.fs(c, 2026, 'pyg', 'P1', null) and (r -> 'total' ->> 'value')::numeric = public.rsum(r),\n         format('clientes = cifra de negocios: %s', public.rsum(r));\n  assert public.rv(r, '43000001') = 118000 and public.rv(r, '43000002') = 2000, 'caso: 118.000 y 2.000 sin IGIC';\n  assert r -> 'rows' -> 0 ->> 'label' = 'Cliente General SL', 'ordenados de mayor a menor';\n  assert r ->> 'base' = 'total';\n  -- Proveedores: compras (Recambios Canarios) e inversión en el torno (Maquinaria Atlántica, grupo 2)\n  r := public.rk(t, 'suppliers');\n  assert public.rv(r, '40000001') = 45000 and public.rv(r, '40000002') = 40000, 'compras e inversión sin IGIC';\n  assert public.rsum(r) = (r -> 'total' ->> 'value')::numeric;\n  -- Gastos por naturaleza: su total = el grupo 6 (la métrica «Gastos» del Resumen de dirección)\n  r := public.rk(t, 'expense_groups');\n  assert (r -> 'total' ->> 'value')::numeric = (select (x.v ->> 'EXPENSES')::numeric from erp.dash_metric_values(c, 2026, array['2026-12-31'::date]) x),\n         'gastos por naturaleza = grupo 6';\n  assert public.rv(r, '60') = 45000 and (select x ->> 'label' from jsonb_array_elements(r -> 'rows') x where x ->> 'key' = '60') = 'Compras',\n         'el subgrupo 60 con su nombre del PGC';\n  assert r ->> 'base' = 'sales' and (r -> 'sales' ->> 'value')::numeric = 120000, 'el % de los gastos, sobre las ventas';\n  raise notice 'OK  · clientes = cifra de negocios, gastos por naturaleza = grupo 6 y el caso al céntimo';\n\n  -- 2027 hasta el 30/06, con el año anterior a la misma fecha\n  t := erp.dashboard_data(c, 'ventas', 2027, '2027-06-30');\n  r := public.rk(t, 'customers');\n  assert (r -> 'total' ->> 'prev')::numeric = public.fs(c, 2026, 'pyg', 'P1', '2026-06-30'), 'el total del año anterior a la misma fecha';\n  raise notice 'OK  · con «hasta» y el año anterior';\nend $$;\n\n-- ---------- Cobros, rectificativas y asientos con dos clientes (en modo guiado: la 430 y la 477 son controladas) ----------\nreset role;\nupdate erp.companies set control_mode = 'guided' where id = (select e from public.ctx where k = 'c');\n-- un segundo cliente para el asiento con dos\ninsert into erp.gl_accounts (company_id, account_no, name, name_en, account_type, template_account, account_category)\nselect company_id, '43000009', 'Cliente Nuevo SL', 'Cliente Nuevo SL', account_type, template_account, account_category\nfrom erp.gl_accounts where company_id = (select e from public.ctx where k = 'c') and account_no = '43000001';\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\ndo $$\ndeclare c uuid := (select e from public.ctx where k = 'c'); fy uuid; a uuid; r0 jsonb; r jsonb;\n        acc_venta uuid; acc_igic uuid;\nbegin\n  fy := (select id from erp.fiscal_years where company_id = c and year = 2027);\n  acc_venta := (select id from erp.gl_accounts where company_id = c and account_no like '700%' and length(account_no) = 8 limit 1);\n  acc_igic := (select id from erp.gl_accounts where company_id = c and account_no = '47710007');\n  r0 := public.rk(erp.dashboard_data(c, 'ventas', 2027), 'customers');\n\n  -- una venta a dos clientes en un asiento: se reparte en proporción (300 y 100)\n  insert into erp.journal_entries (company_id, fiscal_year_id, posting_date, description) values (c, fy, '2027-01-15', 'Venta a dos clientes') returning id into a;\n  insert into erp.journal_lines (entry_id, gl_account_id, debit) values\n    (a, (select id from erp.gl_accounts where company_id = c and account_no = '43000001'), 321),\n    (a, (select id from erp.gl_accounts where company_id = c and account_no = '43000009'), 107);\n  insert into erp.journal_lines (entry_id, gl_account_id, credit) values (a, acc_venta, 400), (a, acc_igic, 28);\n  perform erp.post_entry(a);\n  r := public.rk(erp.dashboard_data(c, 'ventas', 2027), 'customers');\n  assert public.rv(r, '43000001') = coalesce(public.rv(r0, '43000001'), 0) + 300, format('al primero, 300: %s', public.rv(r, '43000001'));\n  assert public.rv(r, '43000009') = 100, 'al segundo, 100';\n\n  -- un cobro no es una venta\n  insert into erp.journal_entries (company_id, fiscal_year_id, posting_date, description) values (c, fy, '2027-01-20', 'Cobro') returning id into a;\n  insert into erp.journal_lines (entry_id, gl_account_id, debit) values (a, (select id from erp.gl_accounts where company_id = c and account_no = '57200001'), 321);\n  insert into erp.journal_lines (entry_id, gl_account_id, credit) values (a, (select id from erp.gl_accounts where company_id = c and account_no = '43000001'), 321);\n  perform erp.post_entry(a);\n  r0 := r;\n  r := public.rk(erp.dashboard_data(c, 'ventas', 2027), 'customers');\n  assert public.rv(r, '43000001') = public.rv(r0, '43000001'), format('el cobro no cuenta: %s', public.rv(r, '43000001'));\n\n  -- una rectificativa (abono) resta\n  insert into erp.journal_entries (company_id, fiscal_year_id, posting_date, description) values (c, fy, '2027-01-25', 'Rectificativa') returning id into a;\n  insert into erp.journal_lines (entry_id, gl_account_id, debit) values (a, acc_venta, 50), (a, acc_igic, 3.5);\n  insert into erp.journal_lines (entry_id, gl_account_id, credit) values (a, (select id from erp.gl_accounts where company_id = c and account_no = '43000009'), 53.5);\n  perform erp.post_entry(a);\n  r := public.rk(erp.dashboard_data(c, 'ventas', 2027), 'customers');\n  assert public.rv(r, '43000009') = 50, 'la rectificativa resta: 100 − 50';\n  assert public.rsum(r) = public.fs(c, 2027, 'pyg', 'P1', null), 'y el total sigue siendo la cifra de negocios';\n  raise notice 'OK  · reparto entre dos clientes, el cobro no cuenta y la rectificativa resta';\nend $$;\n\n-- ---------- Los N primeros y el resto ----------\nreset role;\nupdate erp.dash_widgets set top_n = 1 where dashboard = 'ventas' and source = 'customers';\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\ndo $$\ndeclare c uuid := (select e from public.ctx where k = 'c'); r jsonb;\nbegin\n  r := public.rk(erp.dashboard_data(c, 'ventas', 2026), 'customers');\n  assert jsonb_array_length(r -> 'rows') = 1 and (r -> 'rest' ->> 'count')::int = 1 and (r -> 'rest' ->> 'value')::numeric = 2000,\n         'con 1: el primero y el resto (Cliente Dudoso, 2.000)';\n  assert public.rsum(r) = 120000, 'el total no cambia';\n  raise notice 'OK  · los N primeros y el «Resto»';\nend $$;\nreset role;\nupdate erp.dash_widgets set top_n = 10 where dashboard = 'ventas' and source = 'customers';\n\n-- ---------- Simulación: una venta en edición ----------\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\ndo $$\ndeclare c uuid := (select e from public.ctx where k = 'c'); a uuid; antes jsonb; s jsonb;\nbegin\n  antes := erp.dashboard_data(c, 'ventas', 2027);\n  insert into erp.journal_entries (company_id, fiscal_year_id, posting_date, description)\n  values (c, (select id from erp.fiscal_years where company_id = c and year = 2027), '2027-02-10', 'Venta (borrador)') returning id into a;\n  insert into erp.journal_lines (entry_id, gl_account_id, debit) values (a, (select id from erp.gl_accounts where company_id = c and account_no = '43000002'), 1070);\n  insert into erp.journal_lines (entry_id, gl_account_id, credit) values\n    (a, (select id from erp.gl_accounts where company_id = c and account_no like '700%' and length(account_no) = 8 limit 1), 1000),\n    (a, (select id from erp.gl_accounts where company_id = c and account_no = '47710007'), 70);\n  assert erp.dashboard_data(c, 'ventas', 2027) = antes, 'sin simulación, el borrador no cuenta';\n  s := erp.dashboard_data(c, 'ventas', 2027, null, true);\n  assert public.rv(public.rk(s, 'customers'), '43000002') = coalesce(public.rv(public.rk(antes, 'customers'), '43000002'), 0) + 1000,\n         'con simulación, la venta suma al cliente';\n  assert not erp.simulating();\n  delete from erp.journal_lines where entry_id = a;\n  delete from erp.journal_entries where id = a;\n  raise notice 'OK  · la simulación con una venta en edición';\nend $$;\n\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000b2', false) \\gset\ndo $$\ndeclare c uuid := (select e from public.ctx where k = 'c');\nbegin\n  assert public.falla(format('select erp.dashboard_data(%L, %L, 2026)', c, 'ventas'), 'Not allowed'), 'otra empresa no ve nada';\n  assert not exists (select 1 from erp.dash_ranking(c, 2026, null, 'customers')), 'ni sus clientes';\n  assert not exists (select 1 from erp.dash_ranking(c, 2026, '2026-12-31', 'expense_groups')), 'ni sus gastos';\n  raise notice 'OK  · otra empresa no ve el tablero';\nend $$;\nreset role;\n\n-- ---------- El catálogo ----------\ndo $$\nbegin\n  assert public.falla($q$insert into erp.dash_widgets (dashboard, sort, kind, label, label_en, metrics) values ('ventas', 99, 'ranking', 'x', 'x', '{}')$q$,\n                      'dash_widgets_source_check'), 'un ranking necesita su fuente';\n  assert public.falla($q$insert into erp.dash_widgets (dashboard, sort, kind, source, label, label_en, metrics) values ('ventas', 99, 'bars', 'customers', 'x', 'x', array['SALES'])$q$,\n                      'dash_widgets_source_check'), 'solo el ranking tiene fuente';\n  assert public.falla($q$insert into erp.dash_widgets (dashboard, sort, kind, source, label, label_en, metrics) values ('ventas', 99, 'ranking', 'partners', 'x', 'x', '{}')$q$,\n                      'dash_widgets_source_check'), 'clientes, proveedores o gastos por naturaleza';\n  assert (select count(*) from erp.dashboards where code in ('resumen', 'rentabilidad', 'tesoreria', 'impuestos', 'ventas')) = 5, 'los cinco tableros';   -- 0084: hay más\n  assert not exists (select 1 from erp.dash_widgets w, unnest(w.metrics) m(code)\n                     where not exists (select 1 from erp.dash_metrics x where x.code = m.code)), 'cada tarjeta apunta a métricas que existen';\n  assert not has_function_privilege('anon', 'erp.dash_ranking(uuid, integer, date, text)', 'execute');\n  raise notice 'OK  · catálogo: la tarjeta de ranking y permisos';\nend $$;\n\n-- ---------- Rápido, aunque al lado haya una empresa grande de otro usuario ----------\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000b2', false) \\gset\ndo $$ begin\n  insert into public.ctx values ('grande', (erp.create_case_company('taller_atlantico', 'until_closing')->>'company_id')::uuid);\nend $$;\nreset role;\nselect set_config('request.jwt.claim.sub', '', false) \\gset\nset session_replication_role = replica;\nwith c as (select e as cid from public.ctx where k = 'grande'),\n     fy as (select id from erp.fiscal_years where company_id = (select cid from c) and year = 2026),\n     ins as (insert into erp.journal_entries (company_id, fiscal_year_id, entry_no, posting_date, description, status)\n             select (select cid from c), (select id from fy), 100000 + g, date '2026-01-01' + (g % 360), 'volumen', 'posted'\n             from generate_series(1, 30000) g returning id)\ninsert into erp.journal_lines (company_id, entry_id, gl_account_id, debit, credit, line_no)\nselect (select cid from c), i.id, a.id, case when a.account_no = '62300001' then 10 else 0 end,\n       case when a.account_no = '57200001' then 10 else 0 end, case when a.account_no = '62300001' then 1 else 2 end\nfrom ins i cross join erp.gl_accounts a where a.company_id = (select cid from c) and a.account_no in ('62300001', '57200001');\nset session_replication_role = origin;\nanalyze erp.journal_entries;\nanalyze erp.journal_lines;\n\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\ndo $$\ndeclare c uuid := (select e from public.ctx where k = 'c'); t0 timestamptz; ms numeric;\nbegin\n  t0 := clock_timestamp();\n  perform erp.dashboard_data(c, 'ventas', 2027, '2027-06-30');\n  ms := extract(epoch from clock_timestamp() - t0) * 1000;\n  assert ms < 3000, format('el tablero tarda %s ms', round(ms));\n  raise notice 'OK  · el tablero en % ms con una empresa de 30.000 asientos al lado', round(ms);\nend $$;\nreset role;\n\n\\echo 'FASE 77 OK'\n"}

